const timezone = $('When Executed by Another Workflow').item.json.timezone;
const dataDesejada = $('When Executed by Another Workflow').item.json.data_consulta_reuniao;
const agora = new Date();

// Duração do serviço em minutos
const durationMin = $('duracao do servico').item.json.duration_min;
// Quantos slots de 30min o serviço consome
const slotsNecessarios = Math.ceil(durationMin / 30);

// Extrair offset da data recebida
const offsetMatch = dataDesejada.match(/([+-]\d{2}):(\d{2})$/);
const offsetHoras = offsetMatch ? parseInt(offsetMatch[1]) : 0;
const offsetMinutos = offsetMatch ? parseInt(offsetMatch[2]) : 0;
const offsetTotal = offsetHoras * 60 + (offsetHoras < 0 ? -offsetMinutos : offsetMinutos);

// Pegar horários de funcionamento
const horarios = $('horários de funcionamento').all();

// Pegar agendamentos ocupados
let ocupados = [];
try {
  ocupados = $('agendamentos ocupados').all()
    .filter(item => item.json.scheduled_at)
    .map(item => ({
      inicio: new Date(item.json.scheduled_at),
      fim: new Date(item.json.ends_at)
    }));
} catch(e) {
  ocupados = [];
}

const dataBase = new Date(dataDesejada);
const slotsLivres = [];

for (const horario of horarios) {
  const [hIni] = horario.json.start_time.split(':').map(Number);
  const [hFim] = horario.json.end_time.split(':').map(Number);

  let slotInicio = new Date(dataBase);
  slotInicio.setUTCHours(hIni - (offsetTotal / 60), 0, 0, 0);

  const fim = new Date(dataBase);
  fim.setUTCHours(hFim - (offsetTotal / 60), 0, 0, 0);

  while (slotInicio < fim) {
    const slotFim = new Date(slotInicio);
    slotFim.setUTCMinutes(slotFim.getUTCMinutes() + (slotsNecessarios * 30));

    // Não ultrapassar fim do expediente
    if (slotFim > fim) break;

    // Verificar se está no futuro
    if (slotInicio <= agora) {
      slotInicio = new Date(slotInicio);
      slotInicio.setUTCMinutes(slotInicio.getUTCMinutes() + 30);
      continue;
    }

    // Verificar conflito com agendamentos
    const ocupado = ocupados.some(ag =>
      slotInicio < ag.fim && slotFim > ag.inicio
    );

    if (!ocupado) {
      slotsLivres.push({
        inicio: slotInicio.toISOString(),
        fim: slotFim.toISOString(),
        label: slotInicio.toLocaleString('pt-BR', {
          timeZone: timezone,
          weekday: 'long',
          day: '2-digit',
          month: '2-digit',
          hour: '2-digit',
          minute: '2-digit'
        })
      });
    }

    // Avança 30 minutos
    slotInicio = new Date(slotInicio);
    slotInicio.setUTCMinutes(slotInicio.getUTCMinutes() + 30);
  }
}

// Retornar os 3 primeiros slots livres
const resultado = slotsLivres.slice(0, 3);

if (resultado.length === 0) {
  return [{ json: { 
    slots: [], 
    mensagem: 'Nenhum horário disponível para essa data.'
  }}];
}

return resultado.map(slot => ({ json: slot }));

